(()=>{const rows=[...document.querySelectorAll('.news')],input=document.querySelector('#search'),buttons=[...document.querySelectorAll('[data-filter]')];let group='all';function apply(){const q=input.value.trim().toLowerCase();rows.forEach(r=>r.hidden=(group!=='all'&&r.dataset.group!==group)||!r.textContent.toLowerCase().includes(q));document.querySelector('.empty').hidden=rows.some(r=>!r.hidden);buttons.forEach(b=>{const a=b.dataset.filter===group;b.classList.toggle('active',a);b.setAttribute('aria-pressed',a)})}input.addEventListener('input',apply);buttons.forEach(b=>b.addEventListener('click',()=>{group=b.dataset.filter;apply()}));const lead=document.querySelector('.read-lead'),details=document.querySelector('.hero-details');lead.addEventListener('click',()=>{details.hidden=!details.hidden;lead.setAttribute('aria-expanded',!details.hidden);lead.innerHTML=(details.hidden?'阅读全文':'收起全文')+' <span>↗</span>'});if(!matchMedia('(prefers-reduced-motion: reduce)').matches&&matchMedia('(pointer:fine)').matches){const art=document.querySelector('.hero-art');art.addEventListener('pointermove',e=>{let r=art.getBoundingClientRect();art.style.setProperty('--rx',((e.clientY-r.top)/r.height-.5)*-8+'deg');art.style.setProperty('--ry',((e.clientX-r.left)/r.width-.5)*8+'deg')});art.addEventListener('pointerleave',()=>{art.style.setProperty('--rx','0deg');art.style.setProperty('--ry','0deg')})}apply()})();
